#!/usr/bin/env perl
# -*- coding: utf-8 -*-
use strict;
use warnings;
use Getopt::Long qw(GetOptions);
use File::Basename qw(dirname basename);
use File::Path qw(make_path);
use Cwd qw(abs_path);
use IO::Handle;

STDOUT->autoflush(1);
STDERR->autoflush(1);

# ============================================================
# Script:
#   cluster_sa_split_reads.pl
#
# Purpose:
#   Cluster deletion-like SA split-read events generated by
#   extract_sa_split_reads.pl.
#
# Input:
#   Event-level split-read evidence table.
#
# Required input columns:
#   Sample
#   Read_Name
#   Flag
#   Primary_Chrom
#   Primary_Start
#   Primary_End
#   Primary_CIGAR
#   Primary_MAPQ
#   Primary_Strand
#   SA_Chrom
#   SA_Start
#   SA_End
#   SA_CIGAR
#   SA_MAPQ
#   SA_Strand
#   SA_NM
#   Left_Breakpoint
#   Right_Breakpoint
#   SV_Chrom
#   SV_Start
#   SV_End
#   SV_Length
#   Junction_Type
#   SA_Tag
#
# Required config parameters:
#   SA_SPLIT_CLUSTER_WINDOW
#   SA_SPLIT_MIN_SUPPORT_READS
#
# Output:
#   --outfile
#       PASS cluster summary.
#
#   Derived outputs:
#       *.all_clusters.tsv
#       *.failed_clusters.tsv
#       *.supporting_reads.tsv
#
# Cluster logic:
#   Events are sorted by SV_Chrom, SV_Start and SV_End.
#   Events are grouped when both SV_Start and SV_End are within
#   SA_SPLIT_CLUSTER_WINDOW of the current cluster median.
#
# PASS rule:
#   Support_Reads >= SA_SPLIT_MIN_SUPPORT_READS
#
# Notes:
#   1. Input is expected to contain only Junction_Type=Deletion_Gap events,
#      but this script still checks and skips non-deletion rows if present.
# ============================================================

my $conf    = "";
my $input   = "";
my $outfile = "";
my $help    = 0;

GetOptions(
    "conf=s"    => \$conf,
    "config=s"  => \$conf,
    "input=s"   => \$input,
    "outfile=s" => \$outfile,
    "out=s"     => \$outfile,
    "help"      => \$help,
) or die usage();

if ($help) {
    print usage();
    exit 0;
}

die usage()
    unless defined $conf && $conf ne ""
        && defined $input && $input ne ""
        && defined $outfile && $outfile ne "";

# ------------------------------------------------------------
# Validate runtime I/O
# ------------------------------------------------------------
$conf = abs_path($conf) if -e $conf;
die "[ERROR] Config file not found: $conf\n"
    unless defined $conf && -s $conf;
die "[ERROR] Config path must be absolute after resolution: $conf\n"
    unless $conf =~ m{^/};

$input = abs_path($input) if -e $input;
die "[ERROR] Input split-read event file not found: $input\n"
    unless defined $input && -s $input;
die "[ERROR] Input path must be absolute after resolution: $input\n"
    unless $input =~ m{^/};

die "[ERROR] Output path must be absolute: $outfile\n"
    unless defined $outfile && $outfile =~ m{^/};

my $outdir = dirname($outfile);
make_path($outdir) unless -d $outdir;
die "[ERROR] Cannot create output directory: $outdir\n"
    unless -d $outdir;

# ------------------------------------------------------------
# Read config
# ------------------------------------------------------------
my %CFG = read_conf($conf);

for my $removed_key (qw/
    ANALYZE_CORE_GENES_ONLY
    MIN_SPLIT_READS
    SPLIT_CLUSTER_DISTANCE
/) {
    if (exists $CFG{$removed_key}) {
        die "[ERROR] $removed_key has been removed or replaced.\n"
          . "        Use SA_SPLIT_CLUSTER_WINDOW and SA_SPLIT_MIN_SUPPORT_READS instead.\n"
          . "        Please delete $removed_key from the config file.\n";
    }
}

my $cluster_window = get_conf_required(\%CFG, "SA_SPLIT_CLUSTER_WINDOW");
my $min_support_reads = get_conf_required(\%CFG, "SA_SPLIT_MIN_SUPPORT_READS");

validate_nonnegative_integer("SA_SPLIT_CLUSTER_WINDOW", $cluster_window);
validate_positive_integer("SA_SPLIT_MIN_SUPPORT_READS", $min_support_reads);

# ------------------------------------------------------------
# Derived output files
# ------------------------------------------------------------
my $all_cluster_out = derive_all_clusters_outfile($outfile);
my $failed_out      = derive_failed_clusters_outfile($outfile);
my $support_out     = derive_supporting_reads_outfile($outfile);

print STDERR "[INFO] SA split-read clustering started\n";
print STDERR "[INFO] Config: $conf\n";
print STDERR "[INFO] Input: $input\n";
print STDERR "[INFO] PASS cluster output: $outfile\n";
print STDERR "[INFO] All cluster output: $all_cluster_out\n";
print STDERR "[INFO] Failed cluster output: $failed_out\n";
print STDERR "[INFO] Supporting reads output: $support_out\n";
print STDERR "[INFO] SA_SPLIT_CLUSTER_WINDOW: $cluster_window\n";
print STDERR "[INFO] SA_SPLIT_MIN_SUPPORT_READS: $min_support_reads\n";

# ------------------------------------------------------------
# Read events
# ------------------------------------------------------------
my ($events_ref, $read_stats_ref) = read_split_events($input);
my @events = @{$events_ref};

print STDERR "[INFO] Input data rows: $read_stats_ref->{data_rows}\n";
print STDERR "[INFO] Valid deletion-gap events loaded: " . scalar(@events) . "\n";
print STDERR "[INFO] Skipped non-deletion events: $read_stats_ref->{skipped_non_deletion}\n";
print STDERR "[INFO] Skipped invalid coordinate events: $read_stats_ref->{skipped_invalid_coord}\n";
print STDERR "[INFO] Skipped duplicated events: $read_stats_ref->{skipped_duplicate}\n";

# ------------------------------------------------------------
# Cluster events
# ------------------------------------------------------------
my @clusters = cluster_events(
    events_ref     => \@events,
    cluster_window => $cluster_window,
);

classify_clusters(
    clusters_ref      => \@clusters,
    min_support_reads => $min_support_reads,
);

# ------------------------------------------------------------
# Write outputs
# ------------------------------------------------------------
write_cluster_summary(
    clusters_ref => \@clusters,
    output       => $all_cluster_out,
    mode         => "All",
);

write_cluster_summary(
    clusters_ref => \@clusters,
    output       => $outfile,
    mode         => "Pass",
);

write_cluster_summary(
    clusters_ref => \@clusters,
    output       => $failed_out,
    mode         => "Failed",
);

write_supporting_reads(
    clusters_ref => \@clusters,
    output       => $support_out,
);

my $pass_count = scalar(grep { $_->{Cluster_Status} eq "Pass" } @clusters);
my $failed_count = scalar(@clusters) - $pass_count;

print STDERR "[INFO] SA split-read clustering finished\n";
print STDERR "[INFO] Total clusters: " . scalar(@clusters) . "\n";
print STDERR "[INFO] PASS clusters: $pass_count\n";
print STDERR "[INFO] Failed clusters: $failed_count\n";
print STDERR "[INFO] PASS cluster output: $outfile\n";
print STDERR "[INFO] All cluster output: $all_cluster_out\n";
print STDERR "[INFO] Failed cluster output: $failed_out\n";
print STDERR "[INFO] Supporting reads output: $support_out\n";

exit 0;

# ============================================================
# Config helpers
# ============================================================

sub read_conf {
    my ($file) = @_;

    my %cfg;

    open my $FH, "<", $file
        or die "[ERROR] Cannot open config file: $file\n";

    while (my $line = <$FH>) {
        chomp $line;
        $line =~ s/\r$//;

        next if $line =~ /^\s*$/;
        next if $line =~ /^\s*#/;

        $line =~ s/\s+#.*$//;

        next unless $line =~ /^\s*([^=\s]+)\s*=\s*(.*?)\s*$/;

        my ($key, $val) = ($1, $2);

        $key =~ s/^\s+|\s+$//g;
        $val =~ s/^\s+|\s+$//g;

        $val =~ s/^['"]//;
        $val =~ s/['"]$//;

        die "[ERROR] Empty config key found in $file\n"
            if $key eq "";

        $cfg{$key} = $val;
    }

    close $FH;

    return %cfg;
}

sub get_conf_required {
    my ($cfg_ref, $key) = @_;

    die "[ERROR] Required config parameter missing: $key\n"
        unless exists $cfg_ref->{$key}
            && defined $cfg_ref->{$key}
            && $cfg_ref->{$key} ne "";

    return $cfg_ref->{$key};
}

# ============================================================
# Validation helpers
# ============================================================

sub validate_positive_integer {
    my ($name, $value) = @_;

    die "[ERROR] $name must be a positive integer. Observed: $value\n"
        unless defined $value && $value =~ /^\d+$/ && $value >= 1;

    return 1;
}

sub validate_nonnegative_integer {
    my ($name, $value) = @_;

    die "[ERROR] $name must be a non-negative integer. Observed: $value\n"
        unless defined $value && $value =~ /^\d+$/;

    return 1;
}

# ============================================================
# Input reader
# ============================================================

sub read_split_events {
    my ($file) = @_;

    my @required_cols = qw(
        Sample
        Read_Name
        Flag
        Primary_Chrom
        Primary_Start
        Primary_End
        Primary_CIGAR
        Primary_MAPQ
        Primary_Strand
        SA_Chrom
        SA_Start
        SA_End
        SA_CIGAR
        SA_MAPQ
        SA_Strand
        SA_NM
        Left_Breakpoint
        Right_Breakpoint
        SV_Chrom
        SV_Start
        SV_End
        SV_Length
        Junction_Type
        SA_Tag
    );

    open my $IN, "<", $file
        or die "[ERROR] Cannot open input split-read file: $file\n";

    my $header = <$IN>;

    die "[ERROR] Input split-read file is empty: $file\n"
        unless defined $header;

    chomp $header;
    $header =~ s/\r$//;

    my @cols = split /\t/, $header, -1;
    my %idx;

    for my $i (0 .. $#cols) {
        my $col = $cols[$i];
        $col =~ s/^\s+|\s+$//g;
        $idx{$col} = $i;
    }

    for my $required (@required_cols) {
        die "[ERROR] Required column '$required' not found in input split-read file: $file\n"
            unless exists $idx{$required};
    }

    my @events;
    my %seen_event;

    my %stats = (
        data_rows             => 0,
        skipped_non_deletion  => 0,
        skipped_invalid_coord => 0,
        skipped_duplicate     => 0,
    );

    while (my $line = <$IN>) {
        chomp $line;
        $line =~ s/\r$//;

        next if $line =~ /^\s*$/;

        $stats{data_rows}++;

        my @f = split /\t/, $line, -1;
        my %r;

        for my $col (@required_cols) {
            my $value = exists $idx{$col} ? $f[$idx{$col}] : "NA";
            $value = "NA" unless defined $value && $value ne "";
            $r{$col} = $value;
        }

        if ($r{Junction_Type} ne "Deletion_Gap") {
            $stats{skipped_non_deletion}++;
            next;
        }

        unless (
            is_integer($r{SV_Start})
            && is_integer($r{SV_End})
            && is_integer($r{SV_Length})
            && $r{SV_Chrom} ne "NA"
            && $r{SV_Start} >= 1
            && $r{SV_End} >= $r{SV_Start}
            && $r{SV_Length} >= 1
        ) {
            $stats{skipped_invalid_coord}++;
            next;
        }

        my $dedup_key = join("|",
            $r{Sample},
            $r{Read_Name},
            $r{Primary_Chrom},
            $r{Primary_Start},
            $r{Primary_End},
            $r{Primary_CIGAR},
            $r{SA_Chrom},
            $r{SA_Start},
            $r{SA_End},
            $r{SA_CIGAR},
            $r{SV_Chrom},
            $r{SV_Start},
            $r{SV_End},
        );

        if ($seen_event{$dedup_key}++) {
            $stats{skipped_duplicate}++;
            next;
        }

        push @events, \%r;
    }

    close $IN;

    @events = sort {
        chrom_order_key($a->{SV_Chrom}) cmp chrom_order_key($b->{SV_Chrom})
            || $a->{SV_Start} <=> $b->{SV_Start}
            || $a->{SV_End} <=> $b->{SV_End}
            || $a->{Sample} cmp $b->{Sample}
            || $a->{Read_Name} cmp $b->{Read_Name}
    } @events;

    return (\@events, \%stats);
}

# ============================================================
# Clustering
# ============================================================

sub cluster_events {
    my %args = @_;

    my @events = @{ $args{events_ref} };
    my $cluster_window = $args{cluster_window};

    return () unless @events;

    my @clusters;
    my @current;

    for my $event (@events) {
        if (!@current) {
            @current = ($event);
            next;
        }

        my $current_chr = $current[0]->{SV_Chrom};

        if ($event->{SV_Chrom} ne $current_chr) {
            push @clusters, build_cluster(\@current);
            @current = ($event);
            next;
        }

        my $median_start = int_median(map { $_->{SV_Start} } @current);
        my $median_end   = int_median(map { $_->{SV_End} } @current);

        if (
            abs($event->{SV_Start} - $median_start) <= $cluster_window
            && abs($event->{SV_End} - $median_end) <= $cluster_window
        ) {
            push @current, $event;
        } else {
            push @clusters, build_cluster(\@current);
            @current = ($event);
        }
    }

    push @clusters, build_cluster(\@current) if @current;

    for my $i (0 .. $#clusters) {
        my $cluster_id = sprintf("SR_CLUSTER_%06d", $i + 1);
        $clusters[$i]->{Cluster_ID} = $cluster_id;

        for my $event (@{ $clusters[$i]->{records} }) {
            $event->{Cluster_ID} = $cluster_id;
        }
    }

    return @clusters;
}

sub build_cluster {
    my ($events_ref) = @_;

    my @events = @{$events_ref};

    die "[ERROR] build_cluster received empty event list\n"
        unless @events;

    my @starts  = map { $_->{SV_Start} } @events;
    my @ends    = map { $_->{SV_End} } @events;
    my @lengths = map { $_->{SV_Length} } @events;

    my $cluster_start = int_median(@starts);
    my $cluster_end   = int_median(@ends);
    my $cluster_length = $cluster_end - $cluster_start + 1;
    $cluster_length = 0 if $cluster_length < 0;

    my %sample_count;
    my %read_names;
    my %primary_chrom_count;
    my %primary_strand_count;
    my %sa_chrom_count;
    my %sa_strand_count;
    my %junction_type_count;

    for my $event (@events) {
        $sample_count{ $event->{Sample} }++;
        $read_names{ $event->{Read_Name} }++;
        $primary_chrom_count{ $event->{Primary_Chrom} }++;
        $primary_strand_count{ $event->{Primary_Strand} }++;
        $sa_chrom_count{ $event->{SA_Chrom} }++;
        $sa_strand_count{ $event->{SA_Strand} }++;
        $junction_type_count{ $event->{Junction_Type} }++;
    }

    my @unique_reads = sort keys %read_names;

    return {
        Cluster_ID            => "NA",
        Sample                => join(",", sort keys %sample_count),
        SV_Chrom              => $events[0]->{SV_Chrom},
        Cluster_Start         => $cluster_start,
        Cluster_End           => $cluster_end,
        Cluster_Length        => $cluster_length,

        Support_Reads         => scalar(@unique_reads),
        Support_Records       => scalar(@events),
        Read_Names            => join(",", @unique_reads),

        SV_Start_Median       => $cluster_start,
        SV_End_Median         => $cluster_end,
        SV_Start_Min          => min_num(@starts),
        SV_Start_Max          => max_num(@starts),
        SV_End_Min            => min_num(@ends),
        SV_End_Max            => max_num(@ends),
        SV_Length_Mean        => mean_num(@lengths),
        SV_Length_Min         => min_num(@lengths),
        SV_Length_Max         => max_num(@lengths),

        Primary_Chrom_Count   => format_count_hash(\%primary_chrom_count),
        Primary_Strand_Count  => format_count_hash(\%primary_strand_count),
        SA_Chrom_Count        => format_count_hash(\%sa_chrom_count),
        SA_Strand_Count       => format_count_hash(\%sa_strand_count),
        Junction_Type_Count   => format_count_hash(\%junction_type_count),

        Cluster_Status        => "NA",
        Cluster_Comment       => "NA",
        records               => \@events,
    };
}

sub classify_clusters {
    my %args = @_;

    my $clusters_ref = $args{clusters_ref};
    my $min_support_reads = $args{min_support_reads};

    for my $cluster (@{$clusters_ref}) {
        if ($cluster->{Support_Reads} >= $min_support_reads) {
            $cluster->{Cluster_Status} = "Pass";
            $cluster->{Cluster_Comment} = "Support_Reads >= SA_SPLIT_MIN_SUPPORT_READS";
        } else {
            $cluster->{Cluster_Status} = "LowSupport";
            $cluster->{Cluster_Comment} = "Support_Reads < SA_SPLIT_MIN_SUPPORT_READS";
        }

        for my $event (@{ $cluster->{records} }) {
            $event->{Cluster_ID} = $cluster->{Cluster_ID};
            $event->{Cluster_Status} = $cluster->{Cluster_Status};
        }
    }
}

# ============================================================
# Output writers
# ============================================================

sub write_cluster_summary {
    my %args = @_;

    my $clusters_ref = $args{clusters_ref};
    my $output = $args{output};
    my $mode = $args{mode};

    open my $OUT, ">", $output
        or die "[ERROR] Cannot write cluster summary output: $output\n";

    my @header = qw(
        Sample
        Cluster_ID
        SV_Chrom
        Cluster_Start
        Cluster_End
        Cluster_Length
        Support_Reads
        Support_Records
        Read_Names
        SV_Start_Median
        SV_End_Median
        SV_Start_Range
        SV_End_Range
        SV_Length_Mean
        SV_Length_Range
        Primary_Chrom_Count
        Primary_Strand_Count
        SA_Chrom_Count
        SA_Strand_Count
        Junction_Type_Count
        Cluster_Status
        Cluster_Comment
    );

    print $OUT join("\t", @header), "\n";

    for my $cluster (@{$clusters_ref}) {
        if ($mode eq "Pass") {
            next unless $cluster->{Cluster_Status} eq "Pass";
        } elsif ($mode eq "Failed") {
            next if $cluster->{Cluster_Status} eq "Pass";
        } elsif ($mode eq "All") {
            # keep all clusters
        } else {
            die "[ERROR] Unknown cluster output mode: $mode\n";
        }

        print $OUT join("\t",
            $cluster->{Sample},
            $cluster->{Cluster_ID},
            $cluster->{SV_Chrom},
            $cluster->{Cluster_Start},
            $cluster->{Cluster_End},
            $cluster->{Cluster_Length},
            $cluster->{Support_Reads},
            $cluster->{Support_Records},
            $cluster->{Read_Names},
            $cluster->{SV_Start_Median},
            $cluster->{SV_End_Median},
            $cluster->{SV_Start_Min} . "-" . $cluster->{SV_Start_Max},
            $cluster->{SV_End_Min} . "-" . $cluster->{SV_End_Max},
            sprintf("%.2f", $cluster->{SV_Length_Mean}),
            $cluster->{SV_Length_Min} . "-" . $cluster->{SV_Length_Max},
            $cluster->{Primary_Chrom_Count},
            $cluster->{Primary_Strand_Count},
            $cluster->{SA_Chrom_Count},
            $cluster->{SA_Strand_Count},
            $cluster->{Junction_Type_Count},
            $cluster->{Cluster_Status},
            $cluster->{Cluster_Comment},
        ), "\n";
    }

    close $OUT;
}

sub write_supporting_reads {
    my %args = @_;

    my $clusters_ref = $args{clusters_ref};
    my $output = $args{output};

    open my $OUT, ">", $output
        or die "[ERROR] Cannot write supporting-read output: $output\n";

    my @header = qw(
        Sample
        Cluster_ID
        Cluster_Status
        Read_Name
        Flag
        Primary_Chrom
        Primary_Start
        Primary_End
        Primary_CIGAR
        Primary_MAPQ
        Primary_Strand
        SA_Chrom
        SA_Start
        SA_End
        SA_CIGAR
        SA_MAPQ
        SA_Strand
        SA_NM
        Left_Breakpoint
        Right_Breakpoint
        SV_Chrom
        SV_Start
        SV_End
        SV_Length
        Junction_Type
        SA_Tag
    );

    print $OUT join("\t", @header), "\n";

    for my $cluster (@{$clusters_ref}) {
        for my $event (@{ $cluster->{records} }) {
            my %row = %{$event};
            $row{Cluster_ID} = $cluster->{Cluster_ID};
            $row{Cluster_Status} = $cluster->{Cluster_Status};

            print $OUT join("\t", map { defined $row{$_} ? $row{$_} : "NA" } @header), "\n";
        }
    }

    close $OUT;
}

# ============================================================
# Derived output path helpers
# ============================================================

sub derive_all_clusters_outfile {
    my ($outfile) = @_;

    my $file = $outfile;

    if ($file =~ /\.clusters\.tsv$/) {
        $file =~ s/\.clusters\.tsv$/.all_clusters.tsv/;
    } elsif ($file =~ /\.tsv$/) {
        $file =~ s/\.tsv$/.all_clusters.tsv/;
    } else {
        $file .= ".all_clusters.tsv";
    }

    return $file;
}

sub derive_failed_clusters_outfile {
    my ($outfile) = @_;

    my $file = $outfile;

    if ($file =~ /\.clusters\.tsv$/) {
        $file =~ s/\.clusters\.tsv$/.failed_clusters.tsv/;
    } elsif ($file =~ /\.tsv$/) {
        $file =~ s/\.tsv$/.failed_clusters.tsv/;
    } else {
        $file .= ".failed_clusters.tsv";
    }

    return $file;
}

sub derive_supporting_reads_outfile {
    my ($outfile) = @_;

    my $file = $outfile;

    if ($file =~ /\.clusters\.tsv$/) {
        $file =~ s/\.clusters\.tsv$/.supporting_reads.tsv/;
    } elsif ($file =~ /\.tsv$/) {
        $file =~ s/\.tsv$/.supporting_reads.tsv/;
    } else {
        $file .= ".supporting_reads.tsv";
    }

    return $file;
}

# ============================================================
# General helpers
# ============================================================

sub is_integer {
    my ($value) = @_;
    return defined $value && $value =~ /^-?\d+$/ ? 1 : 0;
}

sub int_median {
    my @values = sort { $a <=> $b } @_;

    return 0 unless @values;

    my $n = scalar(@values);

    if ($n % 2) {
        return int($values[int($n / 2)] + 0.5);
    }

    return int(($values[$n / 2 - 1] + $values[$n / 2]) / 2 + 0.5);
}

sub mean_num {
    my @values = @_;

    return 0 unless @values;

    my $sum = 0;
    $sum += $_ for @values;

    return $sum / scalar(@values);
}

sub min_num {
    my @values = @_;

    die "[ERROR] min_num called with empty list\n"
        unless @values;

    my $min = $values[0];

    for my $v (@values) {
        $min = $v if $v < $min;
    }

    return $min;
}

sub max_num {
    my @values = @_;

    die "[ERROR] max_num called with empty list\n"
        unless @values;

    my $max = $values[0];

    for my $v (@values) {
        $max = $v if $v > $max;
    }

    return $max;
}

sub format_count_hash {
    my ($hash_ref) = @_;

    return "NA" unless %{$hash_ref};

    return join(",", map { $_ . ":" . $hash_ref->{$_} } sort keys %{$hash_ref});
}

sub chrom_order_key {
    my ($chr) = @_;

    my $x = $chr;
    $x =~ s/^chr//i;

    return sprintf("%03d", $x) if $x =~ /^\d+$/;

    my $u = uc($x);

    return "023" if $u eq "X";
    return "024" if $u eq "Y";
    return "025" if $u eq "M" || $u eq "MT";

    return "999_$chr";
}

sub usage {
    return <<'USAGE';
Usage:
  perl bin/cluster_sa_split_reads.pl \
    --conf /abs/path/conf/hcm_exondel.conf \
    --input /abs/path/SAMPLE.split_reads.tsv \
    --outfile /abs/path/SAMPLE.split_reads.clusters.tsv

Required arguments:
  --conf / --config
      HCMExonDel config file.

  --input
      Event-level split-read file generated by extract_sa_split_reads.pl.

  --outfile / --out
      PASS cluster summary output.

Required config parameters:
  SA_SPLIT_CLUSTER_WINDOW
  SA_SPLIT_MIN_SUPPORT_READS

Input columns:
  Sample
  Read_Name
  Flag
  Primary_Chrom
  Primary_Start
  Primary_End
  Primary_CIGAR
  Primary_MAPQ
  Primary_Strand
  SA_Chrom
  SA_Start
  SA_End
  SA_CIGAR
  SA_MAPQ
  SA_Strand
  SA_NM
  Left_Breakpoint
  Right_Breakpoint
  SV_Chrom
  SV_Start
  SV_End
  SV_Length
  Junction_Type
  SA_Tag

Outputs:
  --outfile
      PASS clusters only.

  Derived files:
      *.all_clusters.tsv
      *.failed_clusters.tsv
      *.supporting_reads.tsv

Notes:
  1. Clustering is based on SV_Chrom, SV_Start and SV_End.
  2. Gene and exon annotation should be performed later by annotate_candidates.pl.
USAGE
}

